import { isDeferredChannelSession } from "./deferred-channel-session.js";
const outcomeByResponse = new WeakMap();
export function tagOutcome(response, outcome) {
    outcomeByResponse.set(response, outcome);
    return response;
}
export function dispatchOutcome(response) {
    return outcomeByResponse.get(response);
}
export function skipped(reason, extra = {}) {
    return tagOutcome(Response.json({ ok: true, skipped: true, reason, ...extra }), "skip");
}
/** 202 for a turn whose send completes after the response flushes. */
export function acknowledgeTurn() {
    return tagOutcome(Response.json({ ok: true, dispatched: true, mode: "turn" }, { status: 202 }), "send");
}
/**
 * Report the session a send returned. Hosted admission returns a deferred
 * session: it captured the send and the control plane allocates the real
 * session after acknowledgement, so there is nothing to report yet.
 */
export function turnStarted(session) {
    if (isDeferredChannelSession(session)) {
        return acknowledgeTurn();
    }
    return tagOutcome(Response.json({
        ok: true,
        sessionId: session.id,
        isNew: session.isNew,
        continuationToken: session.continuationToken,
    }), "send");
}
export function isTaskDispatch(dispatch) {
    return "task" in dispatch;
}
/**
 * The task runs after the ack with the per-delivery send, so hosted
 * admission can capture task-initiated sends; a startup-captured send
 * bypasses capture.
 */
export function acknowledgeTask(args, kind, dispatch, extra) {
    scheduleAfterAck(args, kind, () => dispatch.task({ send: args.send, waitUntil: args.waitUntil.bind(args) }));
    return tagOutcome(Response.json({ ok: true, dispatched: true, mode: "task", ...extra }, { status: 202 }), "task");
}
const PROPAGATE_BACKGROUND_ERRORS = Symbol("propagateBackgroundErrors");
/**
 * Hosted admission opts in so a failed background task rejects `waitUntil`
 * (a retryable 503 for the control plane) instead of being logged locally.
 */
export function withPropagatingBackgroundErrors(args) {
    return Object.assign(args, { [PROPAGATE_BACKGROUND_ERRORS]: true });
}
/**
 * Run `work` after the current turn so the 202 flushes first, inside the
 * delivery's `waitUntil` window. Locally a failure is logged and swallowed;
 * see {@link withPropagatingBackgroundErrors} for hosted admission.
 */
export function scheduleAfterAck(args, kind, work) {
    args.waitUntil(new Promise((resolve, reject) => {
        setImmediate(() => {
            Promise.resolve()
                .then(work)
                .then(() => resolve(), (error) => {
                if (args[PROPAGATE_BACKGROUND_ERRORS] === true) {
                    reject(error);
                    return;
                }
                const detail = error instanceof Error ? (error.stack ?? error.message) : String(error);
                console.error(`[${kind}] background dispatch failed: ${detail}`);
                resolve();
            });
        });
    }));
}
